// 예시: 열 때마다 바이옴 2개를 무작위로 골라, 둘 다 스폰 500칸 안에 있는 시드를 3개까지 찾아서 보여줌
ready.then(() => {
  $("threads").value = Math.max(1, Math.min(16, (navigator.hardwareConcurrency || 4) - 1));
  const pool = BIOMES.filter(b => b.g !== "묶음");
  const cfg = { R: 500, cx: 0, cz: 0, step: 32, spawn: 1 };
  const rnd = new Uint32Array(2);
  let cdefs = null, pairT = 0, tries = 0;
  const pickPair = () => {
    const a = pool[Math.floor(Math.random() * pool.length)]; let b;
    do b = pool[Math.floor(Math.random() * pool.length)]; while (b.id === a.id);
    cdefs = colDefs([a.id, b.id], []); pairT = performance.now(); tries++;
    results = results.filter(r => !r.example); selIndex = -1; renderTable();
  };
  pickPair();
  const step = () => {
    if (running || results.some(r => !r.example)) return;       // 사용자가 검색을 시작하면 예시 찾기는 그만
    const m = new Int32Array(mainEx.memory.buffer), ip = mainEx.ids_ptr() >> 2, yp = mainEx.ys_ptr() >> 2;
    cdefs.forEach((c, k) => { m[ip + k] = c.id; m[yp + k] = c.y; });
    const t = performance.now();
    while (performance.now() - t < 40) {
      crypto.getRandomValues(rnd);
      if (!mainEx.test_seed(rnd[0], rnd[1], mainEx.mc_wd(), 2, 500, 32, 0, 0, 1, 0, 0)) continue;
      mainEx.nearest(2, 500, 16, 0, 0, 1, 0);
      const o = mainEx.out_ptr() >> 2, mm = new Int32Array(mainEx.memory.buffer);
      addResult(rnd[0], rnd[1], Array.from(mm.slice(o, o + 6)), cfg, true, [mm[o + 80], mm[o + 81]], cdefs);
      if (results.filter(r => r.example).length >= 3) return;
      break;
    }
    // 너무 드문 조합이면(2초 동안 3개를 못 채우면) 다른 조합으로
    if (performance.now() - pairT > 2000 && tries < 6) pickPair();
    setTimeout(step, 0);
  };
  setTimeout(step, 0);
});
